import { t } from 'elysia'

export const APIEntitiesCdRolloutSchema = t.Object({
  id: t.Optional(t.Integer({ maximum: 9007199254740991, example: 1 })),
  iid: t.Optional(t.Integer({ maximum: 9007199254740991, example: 1 })),
  state: t.Optional(t.String({ example: 'in_progress' })),
  workflow_ref: t.Optional(t.String({ example: 'cd-rollout-1' })),
  started_at: t.Optional(t.Date({ example: '2026-07-22T11:37:00Z' })),
  finished_at: t.Optional(t.Date({ example: '2026-07-22T11:42:00Z' })),
})

export const OrbitQueryResponseSchema = t.Object(
  {
    result: t.Union([t.Object({}), t.String()], {
      externalDocs: {
        description: 'Orbit query response schema',
        url: 'https://gitlab.com/gitlab-org/orbit/knowledge-graph/-/raw/main/config/schemas/query_response.json',
      },
      description:
        'The query result built by the Orbit service. Its shape is set by the Orbit query response schema and versioned by its `format_version` field. An empty string when the Orbit service returns no result.',
    }),
    query_type: t.String({ example: 'traversal', description: 'The type of query that was run.' }),
    raw_query_strings: t.Optional(
      t.Array(t.String(), {
        description:
          'The compiled queries, for debugging. Present only when the Orbit service returns them.',
      }),
    ),
    row_count: t.Integer({
      maximum: 9007199254740991,
      example: 2,
      description: 'The number of rows in the returned page.',
    }),
  },
  { additionalProperties: false },
)

export const APIEntitiesOrbitContextEntitySchema = t.Object({
  token: t.Optional(t.String({ example: 'MergeRequest[123]', description: 'Token as sent.' })),
  resolved_token: t.Optional(
    t.String({
      example: 'MergeRequest[123]',
      description:
        'Token in `Type[id]` form, or `path@ref` for a branch or commit. Present only when `found` is `true`.',
    }),
  ),
  type: t.Optional(
    t.String({
      example: 'MergeRequest',
      description:
        'Type of the entity. Possible values: `MergeRequest`, `WorkItem`, `Job`, `Pipeline`, `Branch`, or `Commit`. `null` when `found` is `false`.',
    }),
  ),
  id: t.Optional(
    t.String({
      example: '123',
      description:
        'Global database ID, in the same form as the node IDs in the graph result, or the branch name or commit SHA. For `iid` and `path@ref` forms, `null` when `found` is `false`. For `Type[id]` and GID tokens, the ID that was sent.',
    }),
  ),
  found: t.Optional(
    t.Boolean({ description: 'If `true`, the entity exists and the user can read it.' }),
  ),
  summary: t.Optional(
    t.Object(
      {},
      {
        description:
          'Summary of a found entity. Contains `namespace_path` and `project_path`. `project_path` is `null` for group work items. Other fields can be added.',
      },
    ),
  ),
  error: t.Optional(
    t.Object(
      {},
      {
        description:
          'Error with a `code`: `invalid_token`, `unsupported_type`, or `not_found`. Present when `found` is `false`.',
      },
    ),
  ),
  expansion: t.Optional(
    t.Object(
      {},
      {
        description:
          '`null` when `expand` is `false` or the token was not found. Otherwise, `result` or `error` with a `code`, plus `query`: the named query that ran or would have run, with `name` and `parameters` (`node_ids` and `limit`). `query` is absent for `expansion_unsupported_type`.',
      },
    ),
  ),
})

export const APIEntitiesOrbitContextSchema = t.Object({
  version: t.Optional(t.String({ example: '1.4.0', description: 'Response contract version.' })),
  entities: t.Optional(
    t.Array(APIEntitiesOrbitContextEntitySchema, {
      description: 'One entry for the one token sent.',
    }),
  ),
})

