export const APIEntitiesAiDuoWorkflowsWorkflowSchema = t.Object({
  id: t.Optional(t.Integer({ maximum: 9007199254740991, description: 'ID of the flow.' })),
  web_url: t.Optional(
    t.String({
      example: 'https://gitlab.example.com/group/project/-/automate/agent-sessions/42',
      description:
        'URL of the session in the GitLab UI. For a group session, the URL is on the top-level group.',
    }),
  ),
  project_id: t.Optional(
    t.Integer({
      maximum: 9007199254740991,
      description: 'ID of the associated project. `null` if not set.',
    }),
  ),
  namespace_id: t.Optional(
    t.Integer({
      maximum: 9007199254740991,
      description: 'ID of the associated namespace. `null` if not set.',
    }),
  ),
  service_account_id: t.Optional(
    t.Integer({
      maximum: 9007199254740991,
      description: 'ID of the service account the flow runs as. `null` if not set.',
    }),
  ),
  agent_privileges: t.Optional(
    t.Array(t.Integer({ maximum: 9007199254740991 }), {
      description: 'Privilege IDs assigned to the agent.',
    }),
  ),
  agent_privileges_names: t.Optional(
    t.Array(t.String(), { description: 'Names corresponding to `agent_privileges`.' }),
  ),
  pre_approved_agent_privileges: t.Optional(
    t.Array(t.Integer({ maximum: 9007199254740991 }), {
      description: 'Privilege IDs the agent can use without asking for approval.',
    }),
  ),
  pre_approved_agent_privileges_names: t.Optional(
    t.Array(t.String(), { description: 'Names corresponding to `pre_approved_agent_privileges`.' }),
  ),
  workflow_definition: t.Optional(t.String({ description: 'Flow type identifier.' })),
  status: t.Optional(
    t.String({
      description:
        'Current flow status. Possible values: `created`, `running`, `paused`, `finished`, `failed`, `stopped`, `input_required`, `plan_approval_required`, `tool_call_approval_required`, or `idle`. GitLab might add new values.',
    }),
  ),
  summary: t.Optional(t.String({ description: 'Short text summary of the workflow.' })),
  title: t.Optional(t.String({ description: 'Title of the session.' })),
  allow_agent_to_request_user: t.Optional(
    t.Boolean({ description: 'If `true`, the agent can pause for user input.' }),
  ),
  image: t.Optional(
    t.String({ description: 'Container image for CI pipeline execution. `null` if not set.' }),
  ),
  environment: t.Optional(t.String({ description: 'Execution environment. `null` if not set.' })),
  ai_catalog_item_version_id: t.Optional(
    t.Integer({
      maximum: 9007199254740991,
      description: 'ID of the AI Catalog item version. `null` if not set.',
    }),
  ),
  workload: t.Optional(
    t.Object(
      {},
      {
        description:
          'Information about the workload: its `id` and a status `message`. The `id` is `null` if no workload was created, for example when `start_workflow` is not `true`.',
      },
    ),
  ),
  mcp_enabled: t.Optional(
    t.Boolean({
      description: 'If `true`, MCP (Model Context Protocol) tools are enabled for the flow.',
    }),
  ),
  incremental_checkpoints_enabled: t.Optional(
    t.Boolean({
      description:
        'If `true`, the workflow stores checkpoints incrementally. `true` for all new workflows. Older workflows can return `false`.',
    }),
  ),
  gitlab_url: t.Optional(t.String({ description: 'Base URL of the GitLab instance.' })),
})

