export const APIEntitiesServiceAccountSchema = t.Object({
  id: t.Optional(
    t.Integer({
      format: 'int64',
      maximum: 9007199254740991,
      example: 1,
      description: 'ID of the user.',
    }),
  ),
  username: t.Optional(t.String({ example: 'admin', description: 'Username of the user.' })),
  public_email: t.Optional(
    t.String({ example: 'john@example.com', description: 'Public email address of the user.' }),
  ),
  name: t.Optional(
    t.String({
      example: 'Administrator',
      description:
        "Name of the user. For a bot user, `****` if the current user cannot read the bot's project or group.",
    }),
  ),
  email: t.Optional(
    t.String({
      example: 'service_account@example.com',
      description: 'Email address of the service account.',
    }),
  ),
  unconfirmed_email: t.Optional(
    t.String({
      example: 'updated_service_account@example.com',
      description:
        'Email address awaiting confirmation. Returned only when a confirmation is pending.',
    }),
  ),
  external: t.Optional(t.Boolean({ example: true })),
})

