export const APIEntitiesDiffSchema = t.Object({
  diff: t.Optional(
    t.String({
      example: '@@ -71,6 +71,8 @@\\n...',
      description: 'Diff of the changes made to the file.',
    }),
  ),
  collapsed: t.Optional(
    t.Boolean({
      description:
        'If `true`, the file diff is excluded but can be fetched on request. [Introduced](https://gitlab.com/gitlab-org/gitlab/-/merge_requests/199633) in GitLab 18.4.',
    }),
  ),
  too_large: t.Optional(
    t.Boolean({
      description:
        'If `true`, the file diff is excluded and cannot be retrieved. [Introduced](https://gitlab.com/gitlab-org/gitlab/-/merge_requests/199633) in GitLab 18.4.',
    }),
  ),
  new_path: t.Optional(
    t.String({ example: 'doc/update/5.4-to-6.0.md', description: 'New path of the file.' }),
  ),
  old_path: t.Optional(
    t.String({ example: 'doc/update/5.4-to-6.0.md', description: 'Old path of the file.' }),
  ),
  a_mode: t.Optional(t.String({ example: '100755', description: 'Old file mode of the file.' })),
  b_mode: t.Optional(t.String({ example: '100644', description: 'New file mode of the file.' })),
  new_file: t.Optional(t.Boolean({ description: 'If `true`, the file was added.' })),
  renamed_file: t.Optional(t.Boolean({ description: 'If `true`, the file was renamed.' })),
  deleted_file: t.Optional(t.Boolean({ description: 'If `true`, the file was removed.' })),
  generated_file: t.Optional(
    t.Boolean({ description: 'If `true`, the file is marked as generated.' }),
  ),
})

