export const PostApiV4ProjectsIdIssuesNoteableIdNotesRequestSchema = t.Object({
  body: t.Union([
    t.String({
      description:
        'Content of the note. Limited to 1,000,000 characters. To promote the issue to an epic, put `/promote` at the start of a line. If the body contains only quick actions, no comment is added.',
    }),
    t.Null(),
  ]),
  confidential: t.Optional(
    t.Union([
      t.Boolean({
        description: 'If `true`, marks the note as internal. Deprecated. Use `internal` instead.',
      }),
      t.Null(),
    ]),
  ),
  internal: t.Optional(
    t.Union([t.Boolean({ description: 'Internal note flag.', default: false }), t.Null()]),
  ),
  created_at: t.Optional(
    t.Union([
      t.String({
        description:
          'Date and time the note was created, in ISO 8601 format such as `2016-03-11T03:45:40Z`. Must be on or after 1970-01-01. Requires administrator or project/group owner rights.',
      }),
      t.Null(),
    ]),
  ),
  merge_request_diff_head_sha: t.Optional(
    t.Union([
      t.String({
        description:
          "SHA of the head commit, which ensures the merge request wasn't updated after the API request was sent. Required for the [`/merge`](https://docs.gitlab.com/user/project/quick_actions/#merge) quick action.",
      }),
      t.Null(),
    ]),
  ),
})

