export const PostApiV4BulkImportsRequestSchema = t.Object({
  configuration: t.Union([
    t.Object(
      {
        url: t.Union([t.String({ description: 'Source GitLab instance URL' }), t.Null()]),
        access_token: t.Union([
          t.String({ description: 'Access token to the source GitLab instance' }),
          t.Null(),
        ]),
      },
      { description: 'The source GitLab instance configuration' },
    ),
    t.Null(),
  ]),
  entities: t.Union([
    t.Array(
      t.Object({
        source_type: t.UnionEnum(['group_entity', 'project_entity'], {
          description: 'Source entity type',
          default: undefined,
        }),
        source_full_path: t.Union([
          t.String({
            example: "'source/full/path' not 'https://example.com/source/full/path'",
            description: 'Relative path of the source entity to import',
          }),
          t.Null(),
        ]),
        destination_namespace: t.Union([
          t.String({
            example: "'destination_namespace' or 'destination/namespace'",
            description:
              'Destination namespace for the entity. Full path of an existing group on the destination instance. For `group_entity`, an empty string `""` creates a top-level group instead. Personal namespaces are not supported.',
          }),
          t.Null(),
        ]),
        destination_slug: t.Optional(
          t.Union([
            t.String({
              example: "'destination_slug' not 'destination/slug'",
              description:
                'Destination slug for the entity. GitLab uses the slug as the URL path to the entity. The name of the imported entity is copied from the name of the source entity, not the slug. Required unless the deprecated `destination_name` is set.',
            }),
            t.Null(),
          ]),
        ),
        destination_name: t.Optional(
          t.Union([
            t.String({
              example: "'destination_slug' not 'destination/slug'",
              description:
                'Deprecated: Use :destination_slug instead. Destination slug for the entity',
            }),
            t.Null(),
          ]),
        ),
        migrate_projects: t.Optional(
          t.Union([
            t.Boolean({
              description: 'Indicates group migration should include nested projects',
              default: true,
            }),
            t.Null(),
          ]),
        ),
        migrate_memberships: t.Optional(
          t.Union([
            t.Boolean({ description: 'The option to migrate memberships or not', default: true }),
            t.Null(),
          ]),
        ),
      }),
      { description: 'List of entities to import' },
    ),
    t.Null(),
  ]),
})

